/* Standalone interactive design preview. All actions stay in browser memory. */
(() => {
  'use strict';
  const M=DVendoDemo,s=M.createState(),$=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const cash=n=>'₱'+Number(n).toLocaleString('en-PH',{maximumFractionDigits:0});
  const date=d=>Number.isInteger(d)?new Date(s.baseDay+d*M.DAY).toLocaleDateString('en-GB',{month:'short',day:'numeric',timeZone:'UTC'}):'Not set';
  const dateInput=d=>Number.isInteger(d)?new Date(s.baseDay+d*M.DAY).toISOString().slice(0,10):'';
  const relative=d=>d===0?'Today':d===1?'Tomorrow':Number.isInteger(d)?`In ${d} days`:'Date needed';
  const initials=name=>name.split(' ').map(n=>n[0]).slice(0,2).join('');
  const paths={
    grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    wallet:'<rect x="3" y="6" width="18" height="14" rx="2"/><path d="M3 10h18m-5 5h2M6 6V3h12v3"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    sim:'<path d="M7 3h9l4 4v14H4V6z"/><rect x="8" y="10" width="8" height="7" rx="1"/><path d="M12 10v7m-4-3h8"/>',
    users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-14a3 3 0 0 1 0 6m2 3a5 5 0 0 1 2 5"/>',
    bag:'<path d="m5 3-2 5v13h18V8l-2-5H5ZM3 8h18m-13 4a4 4 0 0 0 8 0"/>',
    settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',
    history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v5l3 2"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',
    chevron:'<path d="m9 5 7 7-7 7"/>',
    back:'<path d="M20 12H5m5-5-5 5 5 5"/>',
    search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    alert:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3v.1"/>',
    moon:'<path d="M21 13A9 9 0 1 1 11 3a7 7 0 0 0 10 10Z"/>',
    sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',
    bell:'<path d="M4 17h16l-2-3V9a6 6 0 0 0-12 0v5l-2 3Zm6 3h4"/>',
    pause:'<path d="M8 5v14M16 5v14"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5M5.5 7a7 7 0 0 1 12-2L20 8M4 16l2.5 3a7 7 0 0 0 12-2"/>',
    dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    link:'<path d="m9 15 6-6M7 17l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m6 0 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0" transform="translate(2 0) scale(.85 1)"/>'
  };
  const icon=n=>`<svg class="d-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.grid}</svg>`;
  const pill=(text,tone='neutral')=>`<span class="d-pill ${tone}"><i></i>${esc(text)}</span>`;
  const button=(label,action,attrs='',kind='secondary',symbol='')=>`<button type="button" class="d-button ${kind}" data-action="${action}" ${attrs}>${symbol?icon(symbol):''}${label}</button>`;
  const navButton=(label,page,kind='secondary',symbol='')=>button(label,'nav',`data-page="${page}"`,kind,symbol);
  const empty=(title,copy,symbol='sim',action='')=>`<div class="d-empty"><span>${icon(symbol)}</span><h3>${title}</h3><p>${copy}</p>${action}</div>`;
  const sectionHead=(title,copy='',action='')=>`<div class="d-section-head"><div><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>${action}</div>`;
  const metric=(label,value,copy,symbol)=>`<article class="d-metric"><span>${label}${icon(symbol)}</span><strong>${value}</strong><small>${copy}</small></article>`;
  const simButton=(a,tab='overview')=>`<button class="d-name-button" type="button" data-action="open-sim" data-id="${a.id}" data-tab="${tab}">${esc(a.name)}</button>`;
  const managerName=id=>M.manager(s,id)?.name||'Unassigned';
  const allowedManager=['overview','sims','plans','history','settings','sim'];
  const pages={overview:'Supply overview',renewals:'Renewal queue',sims:'Managers & SIMs',catalog:'Promo catalog',history:'History',settings:'Settings',wallet:'Funding plan',plans:'Promo plans'};
  let returnPage='overview',toastTimer,modalReturn=null;

  function notify(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
  function result(r,message){if(!r.ok){notify(r.error);return false;}notify(message);return true;}
  function modal(html){modalReturn=document.activeElement;$('#dialogBody').innerHTML=html;$('#dialog').showModal();}
  function closeModal(){if($('#dialog').open)$('#dialog').close();}
  function modalHead(title){return `<div class="d-modal-head"><h2 id="dialogTitle">${title}</h2>${button('×','close-modal','aria-label="Close dialog"','icon-only')}</div>`;}
  function connection(a){return a.connection.status==='unconnected'?pill('Not connected'):a.connection.status==='stale'?pill('Check is stale','warning'):pill('Connected','success');}
  function planPill(a){const st=M.planStatus(s,a);return pill(st.label,st.tone);}
  function dateText(a){return Number.isInteger(a.plan.day)?`${date(a.plan.day)}<small>${a.plan.dateSource==='planned'?'Planned date':relative(a.plan.day)}</small>`:'<span class="d-muted">Not scheduled</span>';}
  function periodControl(){return `<div class="d-segments" aria-label="Forecast period">${[7,14,30].map(n=>`<button type="button" data-action="period" data-days="${n}" aria-pressed="${s.period===n}">${n} days</button>`).join('')}</div>`;}
  function graph(f){
    const compact=matchMedia('(max-width:650px)').matches,count=compact?4:s.period===7?7:s.period===14?7:6,step=Math.ceil(s.period/count);
    const bars=Array.from({length:count},(_,i)=>({day:i*step,total:f.upcoming.filter(e=>e.day>=i*step&&e.day<(i+1)*step).reduce((sum,e)=>sum+e.price,0)})),max=Math.max(1,...bars.map(b=>b.total));
    return `<div class="d-forecast-chart" role="img" aria-label="Planned renewal cost: ${esc(bars.map(b=>date(b.day)+' '+cash(b.total)).join(', '))}">${bars.map(b=>`<div><span>${b.total?cash(b.total):'—'}</span><i style="height:${Math.max(2,b.total/max*80)}px"></i><small>${s.period===7&&!compact?new Date(s.baseDay+b.day*M.DAY).toLocaleDateString('en',{weekday:'short',timeZone:'UTC'}):date(b.day)}</small></div>`).join('')}</div><p class="d-chart-key">${compact?'Grouped totals · up to '+step+' days per bar':s.period===7?'Daily renewal totals':step+'-day totals'}</p>`;
  }
  function coverage(f){return f.missing.length?`<span>${icon('alert')}${f.missing.length} SIM${f.missing.length===1?' needs':'s need'} a plan, date or resolved attempt. Their unknown future cost is not included.</span>`:`<span>${icon('check')}All enabled SIM plans have dates.</span>`;}
  function fundingCard(){const f=M.forecast(s);return `<section class="d-panel d-funding">${sectionHead('Plan your next top-up','Upcoming renewals across all managers',periodControl())}<div class="d-funding-body"><div><span class="d-eyebrow">RECOMMENDED LOAD TO ADD</span><strong id="fundingEstimate">${cash(f.topup)}</strong><p>${f.topup?`Prepare by <b>${date(f.reserveDay??0)}</b> to protect your reserve.`:'Your wallet covers this window and your reserve.'}</p>${button('View funding plan','nav','data-page="wallet"','primary','arrow')}</div><div class="d-funding-math"><div><span>Planned promos</span><strong>${cash(f.cost)}</strong></div>${f.held?`<div><span>Protected pending amount</span><strong>${cash(f.held)}</strong></div>`:''}<div><span>Keep as reserve</span><strong>${cash(s.reserve)}</strong></div><div><span>Wallet balance</span><strong>− ${cash(s.wallet)}</strong></div></div></div>${graph(f)}<div class="d-coverage">${coverage(f)}<small>Rounded up to ₱100 · planned cost can include offers needing review</small></div></section>`;}
  function attention(){const issues=M.issues(s).slice(0,3);return `<section class="d-panel">${sectionHead('Needs attention',`${M.issues(s).length} items to keep supply moving`,button('View all','notifications','','text','arrow'))}<div class="d-attention-list">${issues.map(i=>`<button type="button" data-action="issue" data-issue="${i.id}" class="d-attention-item"><span class="d-attention-icon">${icon(i.type==='funding'?'wallet':'alert')}</span><span><strong>${i.type==='funding'?'Wallet top-up needed':esc(i.title)}</strong><small>${i.type==='funding'?'Prepare '+cash(M.forecast(s).topup)+' for upcoming renewals':esc(i.detail)}</small></span>${icon('chevron')}</button>`).join('')||empty('All clear','No open supply issues.','check')}</div><div class="d-quiet-note">${icon('clock')}The queue updates when plans, dates or funds change.</div></section>`;}
  function renewalRows(list){return list.map(a=>{const o=M.offer(s,a.plan.offerId);return `<tr><td><div class="d-site-cell"><span class="d-site-icon">${icon('sim')}</span><div>${simButton(a)}<small>•••• ${a.suffix}</small></div></div></td><td>${esc(managerName(a.managerId))}</td><td>${o?esc(o.name):'No promo selected'}<small>${o?o.days+' days':'Choose a plan'}</small></td><td>${dateText(a)}</td><td>${o?cash(o.price):'—'}</td><td>${planPill(a)}</td><td>${button('Open SIM','open-sim',`data-id="${a.id}" data-tab="plan" aria-label="Open renewal plan for ${esc(a.name)}"`,'icon-only','chevron')}</td></tr>`;}).join('');}
  function renewalTable(list,title='Next to supply',copy='Saved plans, soonest first',action=''){return `<section class="d-panel d-table-panel">${sectionHead(title,copy,action)}<div class="d-table-scroll"><table class="d-table d-renewal-table"><thead><tr><th>SIM / site</th><th>Manager</th><th>Next promo</th><th>Renewal</th><th>Est. cost</th><th>Status</th><th aria-label="Open"></th></tr></thead><tbody>${renewalRows(list)}</tbody></table></div>${!list.length?empty('No renewals in this view','Try another filter or add a promo plan.','clock'):''}</section>`;}
  function adminOverview(){const f=M.forecast(s),due=f.upcoming.filter(e=>e.day<7),next=s.sims.filter(a=>a.assignment==='assigned'&&a.plan.auto&&Number.isInteger(a.plan.day)).sort((a,b)=>a.plan.day-b.plan.day).slice(0,5);
    return `<div class="d-page-intro"><div><span class="d-eyebrow">YOUR SUPPLY WORKSPACE</span><h2>Prepare for upcoming renewals.</h2><p>Prepare the load, keep an eye on renewals, and let saved plans guide supply.</p></div><span class="d-date">${new Date(s.baseDay).toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'})} · Philippines</span></div><div class="d-metrics">${metric('Supplier wallet',cash(s.wallet),'Sample balance · last checked just now','wallet')}${metric('Planned over '+s.period+' days',cash(f.cost),f.upcoming.length+' renewal events','clock')}${metric('Managed SIMs',s.sims.length,s.managers.length+' manager portfolios','users')}</div><div class="d-main-grid">${fundingCard()}${attention()}</div>${renewalTable(next,'Next to supply',due.length+' renewal events due within 7 days',navButton('View queue','renewals','text','arrow'))}<section class="d-panel d-portfolios">${sectionHead('Manager portfolios','Upcoming supply, organized by the people managing the SIMs',navButton('View SIMs','sims','text','arrow'))}<div class="d-portfolio-grid">${s.managers.map(m=>{const aa=s.sims.filter(a=>a.managerId===m.id),cost=f.upcoming.filter(e=>e.managerId===m.id).reduce((n,e)=>n+e.price,0);return `<button type="button" class="d-portfolio" data-action="portfolio" data-manager="${m.id}"><span class="d-avatar">${m.initials}</span><span><strong>${esc(m.name)}</strong><small>${aa.length} SIMs · ${esc(m.portfolio)}</small></span><b>${cash(cost)}<small>next ${s.period} days</small></b>${icon('chevron')}</button>`;}).join('')}</div></section>`;}
  function managerCard(a){const c=a.current,o=M.offer(s,a.plan.offerId);return `<article class="d-panel d-sim-card"><div class="d-card-top"><span class="d-site-icon">${icon('sim')}</span>${planPill(a)}</div><h3>${simButton(a)}</h3><p class="d-muted">•••• ${a.suffix}</p>${c?`<div class="d-sim-data"><strong>${c.unlimited?'Unlimited':c.remainingGB.toFixed(1)+' GB'}</strong><span>${c.unlimited?'High-speed data':`of ${c.totalGB} GB remaining`}</span></div>${!c.unlimited?`<div class="d-data-track"><i style="width:${Math.min(100,c.remainingGB/c.totalGB*100)}%"></i></div>`:''}<div class="d-card-fact"><span>Current promo ends</span><b>${date(c.expiryDay)}</b></div>`:`<div class="d-unconnected">${icon('link')}<strong>Monitoring not connected</strong><span>You can still choose a supply plan.</span></div>`}<div class="d-card-plan"><span>Next renewal</span><strong>${o?esc(o.name):'Choose a promo'}</strong><small>${Number.isInteger(a.plan.day)?date(a.plan.day):'Supplier needs to confirm the date'} · ${a.plan.auto?'Automatic plan':'Paused'}</small></div>${button('Manage SIM','open-sim',`data-id="${a.id}"`,'secondary full','arrow')}</article>`;}
  function managerOverview(){const aa=M.visibleSims(s),m=M.manager(s,s.managerId),due=aa.filter(a=>a.plan.auto&&Number.isInteger(a.plan.day)&&a.plan.day<7),attentionCount=aa.filter(a=>M.planStatus(s,a).key!=='scheduled').length;
    return `<div class="d-page-intro"><div><span class="d-eyebrow">${esc(m.portfolio.toUpperCase())}</span><h2>Your SIMs, at a glance.</h2><p>Check current service and choose what each number receives next.</p></div>${button('Add SIM','add-sim','','primary','plus')}</div><div class="d-metrics">${metric('My SIMs',aa.length,'Assigned to your portfolio','sim')}${metric('Renewing within 7 days',due.length,'Using saved promo plans','clock')}${metric('Plans needing attention',attentionCount,'A pause, date or setup needs a look','alert')}</div><div class="d-section-head"><div><h2>My SIMs</h2><p>Current service and the next plan stay separate.</p></div>${navButton('View all','sims','text','arrow')}</div><div class="d-sim-grid">${aa.slice(0,3).map(managerCard).join('')}</div><section class="d-panel d-manager-note"><span class="d-note-icon">${icon('check')}</span><div><h3>Your supplier handles the funding.</h3><p>Save a next-promo preference for each SIM. Supply follows your supplier’s enabled renewal rules.</p></div>${navButton('View promo plans','plans','secondary','arrow')}</section>`;}
  function filterButton(label,value,active,action='queue-filter'){return `<button type="button" class="d-filter ${active===value?'active':''}" data-action="${action}" data-filter="${value}" aria-pressed="${active===value}">${label}</button>`;}
  function queuePage(){let aa=s.sims.filter(a=>a.assignment==='assigned');const test=a=>M.planStatus(s,a).key;
    if(s.queueFilter==='upcoming')aa=aa.filter(a=>a.plan.auto&&Number.isInteger(a.plan.day));
    if(s.queueFilter==='attention')aa=aa.filter(a=>['checking','no-plan','unscheduled','review'].includes(test(a))||a.plan.resumeRequested);
    if(s.queueFilter==='paused')aa=aa.filter(a=>!a.plan.auto);
    if(s.portfolioFilter!=='all')aa=aa.filter(a=>a.managerId===s.portfolioFilter);
    aa.sort((a,b)=>(a.plan.day??Infinity)-(b.plan.day??Infinity));
    return `<div class="d-page-intro"><div><span class="d-eyebrow">FULFILLMENT</span><h2>Know what’s next.</h2><p>Review the selected promo, planned date and any holds before supply.</p></div></div><div class="d-toolbar"><div class="d-filters">${filterButton('Upcoming','upcoming',s.queueFilter)}${filterButton('Needs attention','attention',s.queueFilter)}${filterButton('Paused','paused',s.queueFilter)}${filterButton('All','all',s.queueFilter)}</div><label><span class="d-sr">Filter by manager</span><select id="queuePortfolio" class="d-input"><option value="all">All managers</option>${s.managers.map(m=>`<option value="${m.id}" ${s.portfolioFilter===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label></div>${renewalTable(aa,'Renewal queue',aa.length+' SIMs in this view')}<p class="d-page-note">Plans are not completed purchases. Each supply attempt keeps its own outcome and confirmation record.</p>`;
  }
  function simsPage(){let aa=M.visibleSims(s);if(s.role==='admin'&&s.portfolioFilter!=='all')aa=aa.filter(a=>a.managerId===s.portfolioFilter);if(s.search)aa=aa.filter(a=>`${a.name} ${a.suffix} ${managerName(a.managerId)}`.toLowerCase().includes(s.search.toLowerCase()));if(s.simFilter==='unconnected')aa=aa.filter(a=>a.connection.status==='unconnected');if(s.simFilter==='pending')aa=aa.filter(a=>a.assignment==='pending');
    return `<div class="d-page-intro"><div><span class="d-eyebrow">${s.role==='admin'?'YOUR MANAGERS & NUMBERS':'YOUR PORTFOLIO'}</span><h2>${s.role==='admin'?'Every SIM has a place.':'Manage your SIMs.'}</h2><p>${s.role==='admin'?'Confirm assignments and open a SIM to inspect its service and renewal plan.':'Keep site names, current service and next promos together.'}</p></div>${button('Add SIM','add-sim','','primary','plus')}</div><div class="d-toolbar"><label class="d-search">${icon('search')}<span class="d-sr">Search SIMs</span><input class="d-input" id="simSearch" type="search" placeholder="Search sites, numbers or managers" value="${esc(s.search)}"></label><div class="d-filters">${filterButton('All','all',s.simFilter,'sim-filter')}${filterButton('Not connected','unconnected',s.simFilter,'sim-filter')}${s.role==='admin'?filterButton('Awaiting assignment','pending',s.simFilter,'sim-filter'):''}</div>${s.role==='admin'?`<label><span class="d-sr">SIM portfolio</span><select id="simPortfolio" class="d-input"><option value="all">All managers</option>${s.managers.map(m=>`<option value="${m.id}" ${s.portfolioFilter===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`:''}</div><div class="d-sim-grid">${aa.map(managerCard).join('')}</div>${!aa.length?empty('No SIMs in this view','Try another search or submit a sample SIM.','sim',button('Add SIM','add-sim','','primary','plus')):''}`;
  }
  function plansPage(){return `<div class="d-page-intro"><div><span class="d-eyebrow">PLANNING</span><h2>Choose what comes next.</h2><p>A saved promo preference is used at the next eligible renewal. Your current promo stays unchanged.</p></div></div>${renewalTable(M.visibleSims(s),'My promo plans','Only your assigned SIMs appear here')}<div class="d-info-line">${icon('clock')}You can pause future unsent renewals. Your supplier reviews requests to resume.</div>`;}
  function offerCard(o,selected=false,editable=false){return `<article class="d-offer ${selected?'selected':''}"><div class="d-offer-top"><span>${o.unlimited?'UNLIMITED DATA':o.gb+' GB DATA'}</span>${selected?pill('Selected','success'):''}</div><h3>${esc(o.name)}</h3><p>${esc(o.description)}</p><ul><li>${o.days}-day validity</li><li>Up to 100 Mbps</li></ul><div class="d-offer-price"><strong>${cash(o.price)}</strong><span>per promo</span></div>${editable?`<label class="d-switch-label"><input type="checkbox" role="switch" data-catalog="${o.id}" ${o.enabled?'checked':''} aria-label="Offer ${esc(o.name)} to managers"><span>${o.enabled?'Enabled for managers':'Not offered to managers'}</span></label>`:button(selected?'Selected':'Choose promo','choose-offer',`data-offer="${o.id}" aria-pressed="${selected}"`,selected?'primary full':'secondary full',selected?'check':'plus')}</article>`;}
  function catalogPage(){return `<div class="d-page-intro"><div><span class="d-eyebrow">SUPPLIER CATALOG</span><h2>Make the right options available.</h2><p>Managers choose from your enabled catalog and the offers their SIM is eligible for.</p></div>${pill('Illustrative offers')}</div><div class="d-offer-grid">${s.catalog.map(o=>offerCard(o,false,true)).join('')}</div><div class="d-info-line">${icon('alert')}Offer cards are sample data inspired by your reference. Live eligibility and checkout price still need a provider check.</div>`;}
  function historyRows(orders){return orders.sort((a,b)=>b.day-a.day).map(o=>`<tr><td><button class="d-name-button" type="button" data-action="order-detail" data-order="${o.id}">${esc(o.siteName)}</button><small>${esc(o.id)}</small></td><td>${esc(M.offer(s,o.offerId)?.name||'Promo')}</td><td>${date(o.day)}</td><td>${cash(o.price)}</td><td>${pill(o.status==='unknown'?'Needs checking':o.status.charAt(0).toUpperCase()+o.status.slice(1),o.status==='delivered'?'success':o.status==='failed'?'danger':'warning')}</td><td><button class="d-name-button" type="button" data-action="order-detail" data-order="${o.id}">Details${icon('chevron')}</button></td></tr>`).join('');}
  function historyPage(){let orders=M.visibleOrders(s);if(s.historyFilter!=='all')orders=orders.filter(o=>o.status===s.historyFilter);const funding=s.role==='admin'&&s.historyType==='funding';
    return `<div class="d-page-intro"><div><span class="d-eyebrow">${s.role==='admin'?'FUNDING & FULFILLMENT':'YOUR SUPPLY RECORDS'}</span><h2>A record you can follow.</h2><p>${s.role==='admin'?'Funding and supplied promos are separate events.':'See the outcome of each supply attempt for your SIMs.'}</p></div>${button('Export records','export-history','','secondary','download')}</div><div class="d-toolbar">${s.role==='admin'?`<div class="d-filters">${filterButton('Supply orders','supply',s.historyType,'history-type')}${filterButton('Wallet funding','funding',s.historyType,'history-type')}</div>`:'<span></span>'}${!funding?`<label><span class="d-sr">Filter supply history</span><select id="historyStatus" class="d-input">${['all','delivered','pending','failed','unknown'].map(v=>`<option value="${v}" ${s.historyFilter===v?'selected':''}>${v==='all'?'All results':v==='unknown'?'Needs checking':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label>`:''}</div><section class="d-panel d-table-panel">${sectionHead(funding?'Wallet funding':'Supply orders',funding?'Manual funding records for the sample wallet':orders.length+' records in this view')}<div class="d-table-scroll"><table class="d-table d-history-table"><thead><tr>${funding?'<th>Record</th><th>Source</th><th>Date</th><th>Load added</th>':'<th>SIM / site</th><th>Promo supplied</th><th>Date</th><th>Cost</th><th>Result</th><th></th>'}</tr></thead><tbody>${funding?s.funding.map(r=>`<tr><td><strong>${esc(r.label)}</strong><small>${esc(r.id)}</small></td><td>${esc(r.source)}</td><td>${date(r.day)}</td><td>${cash(r.amount)}</td></tr>`).join(''):historyRows(orders)}</tbody></table></div>${!funding&&!orders.length?empty('No matching supply records','Try a different result filter.','history'):''}</section>`;
  }
  function walletPage(){const f=M.forecast(s);return `<div class="d-page-intro"><div><span class="d-eyebrow">SUPPLIER FUNDING</span><h2>Prepare the load. Protect the plan.</h2><p>You top up your own DITO account manually. The forecast shows what to prepare.</p></div>${button('Record demo top-up','topup','','primary','plus')}</div><div class="d-metrics">${metric('Wallet balance',cash(s.wallet),'Illustrative balance · updated in this preview','wallet')}${metric('Suggested additional load',cash(f.topup),'For the next '+s.period+' days and reserve','plus')}${metric('Reserve',cash(s.reserve),'Kept aside after planned renewals','check')}</div><div class="d-main-grid">${fundingCard()}<section class="d-panel">${sectionHead('What this estimate includes')}<div class="d-detail-facts"><div><span>Planning period</span><strong>${s.period} days</strong></div><div><span>Renewal events</span><strong>${f.upcoming.length}</strong></div><div><span>Protected pending amount</span><strong>${cash(f.held)}</strong></div><div><span>Missing forecast coverage</span><strong>${f.missing.length} SIMs</strong></div></div><p class="d-quiet-copy">Drafts and paused renewals are excluded. Selected offers needing review remain in planned cost. Unknown costs and dates are disclosed.</p>${navButton('Adjust reserve & limits','settings','secondary full','settings')}</section></div>`;}
  function settingsPage(){if(s.role==='manager')return `<div class="d-page-intro"><div><span class="d-eyebrow">YOUR PREFERENCES</span><h2>Keep it personal.</h2><p>Appearance and reminders for your manager workspace.</p></div></div><div class="d-settings-grid"><section class="d-panel">${sectionHead('Profile')}<div class="d-profile"><span class="d-avatar large">${M.manager(s,s.managerId).initials}</span><div><h3>${esc(managerName(s.managerId))}</h3><p>Account Manager · ${esc(M.manager(s,s.managerId).portfolio)}</p></div></div></section><section class="d-panel">${sectionHead('Appearance')}${button('Switch light / dark theme','theme','','secondary','moon')}</section><section class="d-panel">${sectionHead('Notifications','Preferences in this sample workspace')}<label class="d-setting-toggle"><span>Upcoming renewal reminders</span><input type="checkbox" data-notification="renewals" ${s.notifications.renewals?'checked':''}></label><label class="d-setting-toggle"><span>Supply results</span><input type="checkbox" data-notification="results" ${s.notifications.results?'checked':''}></label></section></div>`;
    return `<div class="d-page-intro"><div><span class="d-eyebrow">SUPPLIER RULES</span><h2>Clear limits. Predictable supply.</h2><p>Example controls for the preview. No live automation is enabled.</p></div></div><form id="settingsForm" class="d-settings-grid"><section class="d-panel">${sectionHead('Wallet reserve','Keep a buffer above planned promo costs.')}<label class="d-field"><span>Minimum reserve (₱)</span><input class="d-input" type="number" name="reserve" min="0" max="100000" step="1" required value="${s.reserve}"></label></section><section class="d-panel">${sectionHead('Spending limits','Plans over a limit need supplier review.')}<label class="d-field"><span>Maximum per SIM promo (₱)</span><input class="d-input" type="number" name="perSIM" min="0" max="1000000" step="1" required value="${s.limits.perSIM}"></label><label class="d-field"><span>Manager planned budget · 30 days (₱)</span><input class="d-input" type="number" name="perManager" min="0" max="1000000" step="1" required value="${s.limits.perManager}"></label><label class="d-field"><span>Fleet planned limit per day (₱)</span><input class="d-input" type="number" name="daily" min="0" max="1000000" step="1" required value="${s.limits.daily}"></label></section><section class="d-panel">${sectionHead('Renewal timing')}<div class="d-detail-facts"><div><span>Preview policy</span><strong>At the scheduled date</strong></div><div><span>Manager promo edits</span><strong>Next eligible renewal</strong></div><div><span>In-progress attempts</span><strong>Preserve original order</strong></div></div><p class="d-quiet-copy">Each SIM has an explicit date. Actual provider activation and overlap behavior will determine the live timing policy.</p></section><section class="d-panel">${sectionHead('Appearance')}${button('Switch light / dark theme','theme','','secondary','moon')}<div class="d-form-actions"><button class="d-button primary" type="submit">Save sample settings${icon('check')}</button></div><p class="d-error" id="settingsError" role="alert"></p></section></form>`;
  }

  function simOverview(a){const c=a.current,o=c?M.offer(s,c.offerId):null,next=M.offer(s,a.plan.offerId),state=M.planStatus(s,a);return `<div class="d-detail-grid"><section class="d-panel">${sectionHead('Current service','What the saved account information shows',connection(a))}${c?`<div class="d-current-data"><strong>${c.unlimited?'Unlimited':c.remainingGB.toFixed(1)+' GB'}</strong><span>${c.unlimited?'High-speed data':`of ${c.totalGB} GB remaining`}</span></div>${!c.unlimited?`<div class="d-data-track large"><i style="width:${c.remainingGB/c.totalGB*100}%"></i></div>`:''}<div class="d-detail-facts"><div><span>Active promo</span><strong>${esc(o?.name||'Not returned')}</strong></div><div><span>Expiry</span><strong>${date(c.expiryDay)}</strong></div><div><span>Last successful check</span><strong>${a.connection.status==='stale'?'95 minutes ago':'8 minutes ago'}</strong></div></div>${a.connection.status==='stale'?'<p class="d-inline-warning">This snapshot is stale. It is not a current balance check.</p>':''}`:empty('Monitoring not connected','Current balances and promo expiry are unavailable. This number can still have a recipient supply plan.','link')}</section><section class="d-panel">${sectionHead('Next renewal','A saved preference is separate from current service',planPill(a))}<div class="d-next-offer"><span class="d-site-icon">${icon('bag')}</span><div><h3>${next?esc(next.name):'No promo selected'}</h3><p>${next?cash(next.price)+' · '+next.days+' days':'Choose what this SIM receives next.'}</p></div></div><div class="d-detail-facts"><div><span>Next date</span><strong>${date(a.plan.day)}</strong></div><div><span>Date source</span><strong>${Number.isInteger(a.plan.day)?a.plan.dateSource==='provider'?'Saved promo expiry':'Explicit planned date':'Needs confirmation'}</strong></div><div><span>Funded by</span><strong>Supplier account</strong></div></div><p class="d-quiet-copy">${esc(state.reason)}</p>${button('Manage renewal plan','detail-tab','data-tab="plan"','primary full','arrow')}</section></div><section class="d-panel d-identity">${sectionHead('SIM & assignment')}<div class="d-identity-grid"><div><span>Number</span><strong>•••• ${a.suffix}</strong></div><div><span>Manager</span><strong>${esc(managerName(a.managerId))}</strong></div><div><span>Recipient check</span><strong>${a.validation==='sample-valid'?'Sample recipient accepted':'Provider validation pending'}</strong></div><div><span>Assignment</span><strong>${a.assignment==='assigned'?'Assigned':'Awaiting supplier review'}</strong></div></div>${s.role==='admin'?button(a.assignment==='pending'?'Confirm assignment':'Manage assignment','assignment',`data-id="${a.id}"`,'secondary','users'):''}</section>`;}
  function simPlan(a){const locked=M.inFlight(s,a),chosen=s.drafts[a.id]||a.futurePlan?.offerId||a.plan.offerId,dirty=chosen&&chosen!==(a.futurePlan?.offerId||a.plan.offerId),o=M.offer(s,chosen),enabled=s.catalog.filter(o=>o.enabled);return `${locked?`<div class="d-info-line warning">${icon('clock')}A supply attempt is ${esc(locked.status)}. Any saved choice applies to a following renewal; the existing order stays unchanged.</div>`:''}${a.assignment==='pending'?`<div class="d-info-line">${icon('users')}You can save a preference while Supplier Admin reviews this assignment. No supply is scheduled yet.</div>`:''}<div class="d-plan-layout"><section><div class="d-section-head"><div><h2>Choose the next promo</h2><p>Available sample offers for this recipient.</p></div>${pill('Sample catalog')}</div>${a.validation==='sample-valid'?`<div class="d-offer-grid detail">${enabled.map(o=>offerCard(o,chosen===o.id)).join('')}</div>${!enabled.length?empty('No offers enabled','Your supplier needs to enable an eligible offer.','bag'):''}<div class="d-plan-save"><div><span class="d-eyebrow">${dirty?'UNSAVED CHOICE':a.futurePlan?'SAVED FOR A FOLLOWING RENEWAL':'SAVED NEXT PROMO'}</span><strong>${o?esc(o.name):'Choose an offer above'}</strong><p>${o?cash(o.price)+' · '+o.days+' days':''}</p></div>${s.role==='admin'?'<label class="d-field d-override"><span>Reason for supplier override</span><input class="d-input" id="overrideReason" maxlength="160" placeholder="Explain this change"></label>':''}${button('Save next promo','save-plan',`data-id="${a.id}" ${dirty?'':'disabled'}`,'primary','check')}</div><p class="d-page-note">Saving a plan does not spend load or replace the active promo. Live supply rechecks eligibility, price and supplier limits.</p>`:empty('Recipient validation is pending','Number format alone does not establish an eligible promo catalog.','alert')}</section><aside class="d-panel d-plan-sidebar">${sectionHead('Renewal rule',planPill(a))}<div class="d-detail-facts"><div><span>Next renewal</span><strong>${date(a.plan.day)}</strong></div><div><span>Plan version</span><strong>${a.plan.version}</strong></div><div><span>Rule</span><strong>${a.plan.auto?'Enabled':'Paused'}</strong></div></div>${s.role==='admin'?`<form id="scheduleForm" data-id="${a.id}"><label class="d-field"><span>Scheduled renewal date</span><input class="d-input" type="date" name="date" min="${dateInput(0)}" max="${dateInput(365)}" value="${dateInput(a.plan.day)}" required ${locked?'disabled':''}></label><button type="submit" class="d-button secondary full" ${locked?'disabled':''}>Save date</button></form>${a.current&&!locked?button('Use saved expiry','use-expiry',`data-id="${a.id}"`,'text full','clock'):''}`:`<p class="d-quiet-copy">Your supplier confirms the execution date and controls spending. You can pause future unsent renewals.</p>`}<hr class="d-divider">${a.plan.auto?button('Pause future renewals','pause',`data-id="${a.id}"`,'secondary full','pause'):button(s.role==='admin'?'Enable automatic renewal':a.plan.resumeRequested?'Resume requested':'Request resume','resume',`data-id="${a.id}" ${s.role==='manager'&&a.plan.resumeRequested?'disabled':''}`,'secondary full','refresh')}<p class="d-quiet-copy">Pausing does not cancel a purchase already in progress.</p></aside></div>`;}
  function simHistory(a){const records=M.visibleOrders(s).filter(o=>o.simId===a.id);return `<section class="d-panel d-table-panel">${sectionHead('Supply history','Each attempt has its own recorded result')}<div class="d-table-scroll"><table class="d-table d-history-table"><thead><tr><th>SIM / site</th><th>Promo supplied</th><th>Date</th><th>Cost</th><th>Result</th><th></th></tr></thead><tbody>${historyRows(records)}</tbody></table></div>${!records.length?empty('No supply records yet','A saved promo preference will appear as a supply record only after an attempt is created.','history'):''}</section>`;}
  function simActivity(a){const records=s.audit.filter(r=>r.simId===a.id);return `<section class="d-panel">${sectionHead('Activity','Who changed the plan, rule or assignment')}<ol class="d-activity">${records.map(r=>`<li><span class="d-activity-dot"></span><div><h3>${esc(r.action)}</h3><p>${esc(r.detail)}</p><small>${esc(r.actor)} · just now</small></div></li>`).join('')||'<li><span class="d-activity-dot"></span><div><h3>SIM registered in the sample workspace</h3><p>The starting record belongs to '+esc(managerName(a.managerId))+'.</p><small>Illustrative initial record</small></div></li>'}</ol></section>`;}
  function simPage(){const a=M.sim(s,s.simId);if(!M.canSee(s,a))return empty('SIM not available','This number is not in your current workspace.','sim',navButton('Back to dashboard','overview','primary','back'));return `<button class="d-back-link" type="button" data-action="back-sims">${icon('back')}Back to ${returnPage==='overview'?'dashboard':returnPage==='renewals'?'renewal queue':'SIMs'}</button><div class="d-sim-heading"><div><span class="d-eyebrow">SIM DETAILS</span><h2>${esc(a.name)}</h2><p>•••• ${a.suffix}<span>·</span>${esc(managerName(a.managerId))}</p></div><div>${connection(a)}${planPill(a)}</div></div><div class="d-tabs" role="tablist" aria-label="SIM detail sections">${[['overview','Overview'],['plan','Renewal plan'],['history','Supply history'],['activity','Activity']].map(([key,label])=>`<button type="button" id="tab-${key}" role="tab" aria-selected="${s.tab===key}" aria-controls="simTabPanel" tabindex="${s.tab===key?0:-1}" data-action="detail-tab" data-tab="${key}">${label}</button>`).join('')}</div><div id="simTabPanel" role="tabpanel" aria-labelledby="tab-${s.tab}">${({overview:simOverview,plan:simPlan,history:simHistory,activity:simActivity}[s.tab]||simOverview)(a)}</div>`;}

  function navItems(){return s.role==='admin'?[['overview','Overview','grid'],['renewals','Renewals','clock'],['sims','Managers & SIMs','users'],['catalog','Promo catalog','bag'],['history','History','history'],['settings','Settings','settings']]:[['overview','Overview','grid'],['sims','My SIMs','sim'],['plans','Promo plans','bag'],['history','Supply history','history'],['settings','Settings','settings']];}
  function renderChrome(){const items=navItems(),active=s.page==='sim'?'sims':s.page==='wallet'?'overview':s.page;const entry=([id,label,symbol],compact=false)=>`<button type="button" class="d-nav-item ${active===id?'active':''}" aria-label="${label}" data-action="nav" data-page="${id}" ${active===id?'aria-current="page"':''}>${icon(symbol)}<span>${compact?({overview:"Overview",renewals:"Renewals",sims:s.role==="admin"?"SIMs":"My SIMs",plans:"Plans",history:"History"}[id]||label):label}</span>${id==='renewals'&&M.issues(s).length?`<small>${M.issues(s).length}</small>`:''}</button>`;
    $('#sideNav').innerHTML=items.map(item=>entry(item)).join('');const core=items.slice(0,3),extra=items.slice(3);$('#mobileNav').innerHTML=core.map(item=>entry(item,true)).join('')+`<details class="d-mobile-more"><summary>${icon('dots')}<span>More</span></summary><div>${extra.map(item=>entry(item)).join('')}${button('Switch theme','theme','','text','moon')}</div></details>`;
    $('#userName').textContent=s.role==='admin'?'Supplier workspace':managerName(s.managerId);$('#userRole').textContent=s.role==='admin'?'Supplier Admin':'Account Manager';$('#userAvatar').textContent=s.role==='admin'?'SA':M.manager(s,s.managerId).initials;
    $('#previewRole').value=s.role;$('#previewManager').classList.toggle('hidden',s.role!=='manager');$('#previewManager').value=s.managerId;
    $('#pageTitle').textContent=s.page==='sim'?'SIM details':s.role==='manager'&&s.page==='overview'?'My dashboard':s.role==='manager'&&s.page==='sims'?'My SIMs':pages[s.page]||'Overview';
    $('#pageEyebrow').textContent=s.role==='admin'?'SUPPLIER ADMIN':'ACCOUNT MANAGER';$('#themeButton').innerHTML=icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')+'<span>Appearance</span>';
  }
  function render(){
    if(!pages[s.page]&&s.page!=='sim')s.page='overview';
    if(s.role==='manager'&&!allowedManager.includes(s.page))s.page='overview';
    if(s.page==='sim'&&!M.canSee(s,M.sim(s,s.simId))){s.page='overview';s.simId=null;}
    renderChrome();$('#workspace').innerHTML=({overview:()=>s.role==='admin'?adminOverview():managerOverview(),renewals:queuePage,sims:simsPage,plans:plansPage,catalog:catalogPage,history:historyPage,settings:settingsPage,wallet:walletPage,sim:simPage}[s.page]||adminOverview)()+`<footer class="d-footer"><span>DVendo Supply</span><span>Sample data · changes reset when you reload</span></footer>`;
  }
  function route(){return s.page==='sim'?`sim/${s.simId}/${s.tab}`:s.page;}
  function updateURL(){history.pushState(null,'','#'+route());}
  function navigate(page){s.page=page;s.simId=null;render();updateURL();window.scrollTo({top:0,behavior:'instant'});$('#pageTitle').focus({preventScroll:true});}
  function openSIM(id,tab='overview'){const a=M.sim(s,id);if(!M.canSee(s,a)){notify('This SIM is outside your portfolio.');return;}if(s.page!=='sim')returnPage=s.page;s.simId=id;s.page='sim';s.tab=['overview','plan','history','activity'].includes(tab)?tab:'overview';render();updateURL();window.scrollTo({top:0,behavior:'instant'});}
  function readRoute(){const parts=location.hash.slice(1).split('/');if(parts[0]==='sim'){s.page='sim';s.simId=parts[1];s.tab=parts[2]||'overview';}else if(parts[0])s.page=parts[0];render();}
  function switchRole(){closeModal();s.role=$('#previewRole').value;s.managerId=$('#previewManager').value;s.page='overview';s.simId=null;s.search='';s.portfolioFilter='all';render();history.replaceState(null,'','#overview');window.scrollTo(0,0);}
  function showTopup(){if(s.role!=='admin')return;modal(`${modalHead('Record a demo top-up')}<p class="d-modal-copy">Try the funding forecast with more load. This changes the sample wallet only.</p><form id="topupForm"><label class="d-field"><span>Demo load amount (₱)</span><input class="d-input" name="amount" type="number" min="1" max="100000" step="1" value="${M.forecast(s).topup||500}" required></label><p class="d-error" id="topupError" role="alert"></p><div class="d-modal-actions">${button('Cancel','close-modal')}<button class="d-button primary" type="submit">Add demo load${icon('plus')}</button></div></form>`);}
  function showAssignment(id){const a=M.sim(s,id);if(s.role!=='admin'||!a)return;modal(`${modalHead(a.assignment==='pending'?'Confirm SIM assignment':'Move to a portfolio')}<p class="d-modal-copy">${esc(a.name)} · •••• ${a.suffix}</p><form id="assignmentForm" data-id="${id}"><label class="d-field"><span>Account Manager</span><select name="manager" class="d-input">${s.managers.map(m=>`<option value="${m.id}" ${m.id===a.managerId?'selected':''}>${esc(m.name)} · ${esc(m.portfolio)}</option>`).join('')}</select></label><p class="d-quiet-copy">The assigned manager can see this SIM. Earlier supply records retain their original manager.</p><p class="d-error" id="assignmentError" role="alert"></p><div class="d-modal-actions">${button('Cancel','close-modal')}<button class="d-button primary" type="submit">Confirm assignment</button></div></form>`);}
  function showAdd(){modal(`${modalHead('Add a SIM')}<p class="d-modal-copy">Register a recipient in ${s.role==='admin'?'a manager portfolio':'your portfolio'}. Monitoring is connected separately.</p><form id="addSIMForm"><label class="d-field"><span>SIM number</span><input name="number" id="newSIMNumber" class="d-input" type="tel" placeholder="Enter a number or use a sample" autocomplete="off" required></label><div class="d-inline-actions">${button('Use sample SIM','sample-number','','text','sim')}${button('Check number format','check-number','','secondary','check')}</div><div id="numberValidation" class="d-validation" role="status"></div><label class="d-field"><span>Site name</span><input class="d-input" name="name" maxlength="70" placeholder="e.g. Warehouse entrance" required></label>${s.role==='admin'?`<label class="d-field"><span>Manager portfolio</span><select name="manager" class="d-input">${s.managers.map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(m.portfolio)}</option>`).join('')}</select></label>`:''}<p class="d-quiet-copy">${s.role==='manager'?'Supplier Admin confirms the assignment. ':''}Format checking does not prove DITO eligibility. No raw number is retained in this preview.</p><p class="d-error" id="addSIMError" role="alert"></p><div class="d-modal-actions">${button('Cancel','close-modal')}<button class="d-button primary" id="submitSIM" type="submit" disabled>${s.role==='manager'?'Submit SIM':'Add SIM'}</button></div></form>`);}
  function checkNumber(){const form=$('#addSIMForm'),raw=form.elements.number.value.trim(),sample=/^DEMO-\d{4}$/.test(raw);let digits=raw.replace(/\D/g,'');if(digits.startsWith('63'))digits=digits.slice(2);else if(digits.startsWith('0'))digits=digits.slice(1);const valid=sample||/^9\d{9}$/.test(digits);$('#numberValidation').textContent=valid?(sample?'Sample recipient ready. This is not a live validation.':'Format accepted. Provider validation is still pending.'):'Enter a valid local format, or use a sample SIM.';form.dataset.suffix=valid?(sample?raw.slice(-4):digits.slice(-4)):'';form.dataset.sample=sample?'yes':'no';form.dataset.checkedValue=raw;$('#submitSIM').disabled=!valid;}
  function showNotifications(){const issues=s.role==='admin'?M.issues(s):M.visibleSims(s).filter(a=>M.planStatus(s,a).key!=='scheduled').map(a=>({id:a.id,simId:a.id,type:M.planStatus(s,a).key,title:M.planStatus(s,a).label,detail:a.name,action:'sim'}));modal(`${modalHead('Needs attention')}<p class="d-modal-copy">${s.role==='admin'?'Funding, scheduling and supplier review.':'Plan and setup updates for your assigned SIMs.'}</p><div class="d-modal-issues">${issues.map(i=>`<button type="button" class="d-attention-item" data-action="issue" data-issue="${i.id}"><span class="d-attention-icon">${icon('alert')}</span><span><strong>${esc(i.type==='funding'?'Supplier funding needed':i.title)}</strong><small>${esc(i.detail)}</small></span>${icon('chevron')}</button>`).join('')||empty('All clear','There are no open plan issues.','check')}</div>`);}
  function handleIssue(id){closeModal();const a=M.sim(s,id);if(a&&M.canSee(s,a)){openSIM(a.id,a.assignment==='pending'?'overview':'plan');return;}const issue=M.issues(s).find(i=>i.id===id);navigate(issue?.action==='wallet'?'wallet':'settings');}
  function showOrder(id){const o=M.visibleOrders(s).find(o=>o.id===id);if(!o)return;const a=M.sim(s,o.simId);modal(`${modalHead('Supply record')}<p class="d-modal-copy">${esc(o.siteName)} · ${esc(o.id)}</p><div class="d-detail-facts"><div><span>Promo</span><strong>${esc(M.offer(s,o.offerId)?.name)}</strong></div><div><span>Cost</span><strong>${cash(o.price)}</strong></div><div><span>Result</span><strong>${esc(o.status)}</strong></div><div><span>Date</span><strong>${date(o.day)}</strong></div><div><span>Reference</span><strong>${esc(o.reference||'Not returned')}</strong></div><div><span>Plan version</span><strong>${o.planVersion}</strong></div></div><p class="d-quiet-copy">Illustrative supply record. A reference alone would not establish delivery in the working service.</p><div class="d-modal-actions">${button('Close','close-modal')}${M.canSee(s,a)?button('Open SIM','order-open-sim',`data-id="${a.id}"`,'primary','arrow'):''}</div>`);}
  function exportHistory(){const funding=s.role==='admin'&&s.historyType==='funding',rows=funding?[['Record','Date','Amount'],...s.funding.map(r=>[r.id,date(r.day),r.amount])]:[['Record','Site','Promo','Date','Cost','Result'],...M.visibleOrders(s).filter(o=>s.historyFilter==='all'||o.status===s.historyFilter).map(o=>[o.id,o.siteName,M.offer(s,o.offerId)?.name,date(o.day),o.price,o.status])];const text='Sample data — DVendo Supply\r\n'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='dvendo-sample-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Sample records exported.');}

  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
    if(action==='nav'){closeModal();navigate(el.dataset.page);}
    if(action==='open-sim')openSIM(el.dataset.id,el.dataset.tab);
    if(action==='back-sims')navigate(['overview','renewals','sims','plans'].includes(returnPage)?returnPage:'sims');
    if(action==='detail-tab'){s.tab=el.dataset.tab;render();updateURL();$(`#tab-${s.tab}`)?.focus({preventScroll:true});}
    if(action==='period'){s.period=Number(el.dataset.days);render();}
    if(action==='queue-filter'){s.queueFilter=el.dataset.filter;render();}
    if(action==='sim-filter'){s.simFilter=el.dataset.filter;render();}
    if(action==='history-type'){s.historyType=el.dataset.filter;render();}
    if(action==='portfolio'){s.portfolioFilter=el.dataset.manager;navigate('sims');}
    if(action==='choose-offer'){const a=M.sim(s,s.simId);if(!M.canSee(s,a))return;s.drafts[a.id]=el.dataset.offer;render();}
    if(action==='save-plan'){const a=M.sim(s,el.dataset.id),o=s.drafts[a.id];const r=M.savePlan(s,a.id,o,$('#overrideReason')?.value||'');if(result(r,r.following?'Saved for a following renewal. The current attempt is unchanged.':r.review?'Preference saved. Supplier budget review is needed.':'Next promo saved. No purchase was made.'))render();}
    if(action==='pause'){if(result(M.pause(s,el.dataset.id),'Future renewals paused. In-progress attempts are unchanged.'))render();}
    if(action==='resume'){const r=M.resume(s,el.dataset.id);if(result(r,r.requested?'Resume request sent to the sample supplier inbox.':'Sample automatic renewal rule enabled.'))render();}
    if(action==='use-expiry'){const a=M.sim(s,el.dataset.id);if(result(M.setDate(s,a.id,a.current.expiryDay,'provider'),'Renewal date set from the saved expiry.'))render();}
    if(action==='topup')showTopup();if(action==='add-sim')showAdd();if(action==='assignment')showAssignment(el.dataset.id);
    if(action==='close-modal')closeModal();if(action==='notifications')showNotifications();if(action==='issue')handleIssue(el.dataset.issue);
    if(action==='order-detail')showOrder(el.dataset.order);if(action==='order-open-sim'){closeModal();openSIM(el.dataset.id);}
    if(action==='sample-number'){const form=$('#addSIMForm');form.elements.number.value='DEMO-'+String(9000+s.nextId);if(!form.elements.name.value)form.elements.name.value='New sample site';checkNumber();}
    if(action==='check-number')checkNumber();if(action==='export-history')exportHistory();
    if(action==='theme'){const value=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=value;try{localStorage.setItem('supplier-preview-theme',value);}catch{}renderChrome();$('meta[name="theme-color"]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();}
    if(action==='reset'){location.reload();}
  });
  document.addEventListener('change',e=>{const el=e.target;
    if(el.id==='previewRole'||el.id==='previewManager')switchRole();
    if(el.id==='queuePortfolio'||el.id==='simPortfolio'){s.portfolioFilter=el.value;render();}
    if(el.id==='historyStatus'){s.historyFilter=el.value;render();}
    if(el.dataset.catalog){if(result(M.catalogToggle(s,el.dataset.catalog),'Sample catalog updated. Existing selections stay visible for review.'))render();}
    if(el.dataset.notification)s.notifications[el.dataset.notification]=el.checked;
  });
  document.addEventListener('input',e=>{if(e.target.id==='simSearch'){const pos=e.target.selectionStart;s.search=e.target.value;render();const field=$('#simSearch');field.focus();field.setSelectionRange(pos,pos);}if(e.target.id==='newSIMNumber'){const form=$('#addSIMForm');form.dataset.suffix='';$('#submitSIM').disabled=true;$('#numberValidation').textContent='';}});
  document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);
    if(form.id==='topupForm'){const r=M.topup(s,Number(data.get('amount')));if(!r.ok){$('#topupError').textContent=r.error;return;}closeModal();render();notify('Demo wallet updated. No real top-up was made.');}
    if(form.id==='assignmentForm'){const r=M.assign(s,form.dataset.id,data.get('manager'));if(!r.ok){$('#assignmentError').textContent=r.error;return;}closeModal();render();notify('Sample SIM assignment confirmed.');}
    if(form.id==='scheduleForm'){const day=(Date.parse(data.get('date')+'T00:00:00Z')-s.baseDay)/M.DAY;if(result(M.setDate(s,form.dataset.id,day),'Planned renewal date saved.'))render();}
    if(form.id==='settingsForm'){const values=Object.fromEntries(['reserve','perSIM','perManager','daily'].map(k=>[k,Number(data.get(k))]));if(Object.values(values).some(v=>!Number.isInteger(v)||v<0)||values.reserve>100000||[values.perSIM,values.perManager,values.daily].some(v=>v>1000000)){$('#settingsError').textContent='Use whole, non-negative amounts within the displayed limits.';return;}for(const key of ['perSIM','perManager','daily'])M.setLimit(s,key,values[key]);M.setReserve(s,values.reserve);render();notify('Sample reserve and spending limits saved.');}
    if(form.id==='addSIMForm'){if(!form.dataset.suffix||form.dataset.checkedValue!==String(data.get('number')).trim()){$('#addSIMError').textContent='Check the number first.';return;}const r=M.addSIM(s,{name:data.get('name'),suffix:form.dataset.suffix,sample:form.dataset.sample==='yes',managerId:data.get('manager')});if(!r.ok){$('#addSIMError').textContent=r.error;return;}closeModal();openSIM(r.sim.id);notify(s.role==='manager'?'Sample SIM submitted for supplier assignment.':'Sample SIM added. Choose a promo and renewal date next.');}
  });
  $('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
  $('#dialog').addEventListener('close',()=>{if(modalReturn?.isConnected)modalReturn.focus();else $('#pageTitle').focus({preventScroll:true});});
  document.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key)||!e.target.closest('[role="tablist"]'))return;const tabs=$$('[role="tab"]'),index=tabs.indexOf(e.target);e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();});
  window.addEventListener('popstate',readRoute);
  matchMedia('(max-width:650px)').addEventListener('change',()=>{if(['overview','wallet'].includes(s.page))render();});
  $('#previewManager').innerHTML=s.managers.map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(m.portfolio)}</option>`).join('');
  const params=new URLSearchParams(location.search);if(params.get('role')==='manager'){s.role='manager';if(s.managers.some(m=>m.id===params.get('manager')))s.managerId=params.get('manager');}
  readRoute();
  globalThis.DVendoPreview={state:s,model:M,render,navigate,openSIM};
})();
